#include "noe.hpp"
#include <iostream>
namespace noe { int TestRunner::runDirectory(const std::filesystem::path& dir)const{if(!std::filesystem::exists(dir)){std::cerr<<"NQR-TEST7000: test directory not found: "<<dir<<"\n";return 1;}int failed=0,total=0;for(auto&e:std::filesystem::recursive_directory_iterator(dir)){if(!e.is_regular_file()||e.path().extension()!=".noqeri")continue;++total;try{auto c=compileFile(e.path());if(c.diagnostics.hasErrors()){++failed;std::cerr<<"FAIL "<<e.path()<<"\n";c.diagnostics.print(e.path().string());}else{Interpreter i;int rc=i.run(c.nir);if(rc){++failed;std::cerr<<"FAIL "<<e.path()<<"\n";}else std::cout<<"PASS "<<e.path()<<"\n";}}catch(const std::exception&ex){++failed;std::cerr<<"FAIL "<<e.path()<<": "<<ex.what()<<"\n";}}std::cout<<"noqeri tests: "<<(total-failed)<<" passed, "<<failed<<" failed, "<<total<<" total\n";return failed?1:0;} }
